<?php
require_once __DIR__.'/../includes/auth.php';$u=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=clean_text($_POST['title']??'',180,true,'Advertisement title');$description=clean_text($_POST['description']??'',500,false,'Description');$targetUrl=validated_http_url($_POST['target_url']??'',255);$placement=clean_text($_POST['placement']??'homepage',80,true,'Placement');if(!preg_match('/^[a-z0-9_-]+$/i',$placement))throw new RuntimeException('Placement is invalid.');$status=(string)($_POST['status']??'draft');if(!in_array($status,['draft','active','paused','expired'],true))throw new RuntimeException('Advertisement status is invalid.');$starts=nullable_datetime_local($_POST['starts_at']??null,'Start date/time');$ends=nullable_datetime_local($_POST['ends_at']??null,'End date/time');if($starts&&$ends&&$ends<$starts)throw new RuntimeException('End date/time must be after the start.');$budget=nullable_money($_POST['budget']??0,'Budget')??0;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect('admin/advertisements.php');}$q=db()->prepare("INSERT INTO advertisements(title,description,target_url,placement,status,starts_at,ends_at,created_by,budget) VALUES(?,?,?,?,?,?,?,?,?)");$q->execute([$title,$description?:null,$targetUrl,$placement,$status,$starts,$ends,$u['id'],$budget]);log_activity((int)$u['id'],'advertisement_created','advertisement',(int)db()->lastInsertId(),$title);flash('success','Advertisement created.');redirect('admin/advertisements.php');}
$pg=pagination_window(30,60);$q=db()->prepare('SELECT id,title,placement,status,budget,impressions,clicks,created_at FROM advertisements ORDER BY id DESC LIMIT '.($pg['per']+1).' OFFSET '.$pg['offset']);$q->execute();$ads=$q->fetchAll();$hasNext=trim_page_results($ads,$pg['per']);$success=flash('success');$error=flash('error');release_session_lock();$pageTitle='Advertisements — Admin';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Advertisements</h1><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-3 mb-4"><form method="post" class="row g-2"><?=csrf_field()?><div class="col-md-4"><input class="form-control" name="title" maxlength="180" placeholder="Campaign title" required></div><div class="col-md-4"><input class="form-control" name="target_url" maxlength="255" placeholder="Target URL"></div><div class="col-md-2"><input class="form-control" name="budget" type="number" min="0" step="0.01" placeholder="Budget"></div><div class="col-md-2"><select class="form-select" name="status"><option>draft</option><option>active</option><option>paused</option></select></div><div class="col-md-6"><input class="form-control" name="description" maxlength="500" placeholder="Description"></div><div class="col-md-2"><input class="form-control" name="placement" maxlength="80" value="homepage"></div><div class="col-md-2"><input class="form-control" type="datetime-local" name="starts_at"></div><div class="col-md-2"><input class="form-control" type="datetime-local" name="ends_at"></div><div><button class="btn btn-primary">Create advertisement</button></div></form></div><div class="table-responsive"><table class="table"><tr><th>Campaign</th><th>Placement</th><th>Status</th><th>Budget</th><th>Impressions</th><th>Clicks</th></tr><?php foreach($ads as $a):?><tr><td><?=e($a['title'])?></td><td><?=e($a['placement'])?></td><td><?=e($a['status'])?></td><td>₹<?=number_format((float)$a['budget'],2)?></td><td><?=(int)$a['impressions']?></td><td><?=(int)$a['clicks']?></td></tr><?php endforeach;?></table></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
